// ==UserScript==
// @name         小红书自动获客助手
// @namespace    https://github.com/xhs-comment-assistant
// @version      2.2.1
// @icon         https://raw.githubusercontent.com/onedarren/XHShuokezhushou/main/docs/logo.png
// @description  小红书自动获客助手：支持点赞、收藏、评论（表情/文本/AI），关键词搜索模式，界面与工具模块开源（MIT），核心引擎闭源。
// @author       xhs-comment-assistant
// @homepageURL  https://github.com/onedarren/XHShuokezhushou
// @supportURL   https://github.com/onedarren/XHShuokezhushou/issues
// @match        https://www.xiaohongshu.com/*
// @run-at       document-idle
// @noframes
// @grant        unsafeWindow
// @grant        GM_setValue
// @grant        GM_getValue
// @grant        GM_deleteValue
// @grant        GM_xmlhttpRequest
// @grant        GM_notification
// @connect      api.deepseek.com
// @connect      api.moonshot.cn
// @connect      api.openai.com
// @connect      openrouter.ai
// @connect      generativelanguage.googleapis.com
// @connect      api.xiaomimimo.com
// @connect      127.0.0.1
// @connect      localhost
// @connect      *
